package com.bank.deploy.model;

// Models an EKS Deployment moving through a rollout.
public class Deployment {
    private final String name;
    private String currentImageTag;       // the live, known-good image
    private String targetImageTag;        // the new image being rolled out
    private int readyReplicas;
    private final int desiredReplicas;
    private RolloutStatus status = RolloutStatus.PENDING;

    public Deployment(String name, String currentImageTag, int desiredReplicas) {
        this.name = name;
        this.currentImageTag = currentImageTag;
        this.desiredReplicas = desiredReplicas;
    }

    public String getName() { return name; }
    public String getCurrentImageTag() { return currentImageTag; }
    public String getTargetImageTag() { return targetImageTag; }
    public int getReadyReplicas() { return readyReplicas; }
    public int getDesiredReplicas() { return desiredReplicas; }
    public RolloutStatus getStatus() { return status; }

    public void setTargetImageTag(String t) { this.targetImageTag = t; }
    public void setReadyReplicas(int n) { this.readyReplicas = n; }
    public void setStatus(RolloutStatus s) { this.status = s; }
    public void promoteTargetToCurrent() { this.currentImageTag = targetImageTag; }
}
