package com.bank.deploy.pipeline;

import com.bank.deploy.model.*;
import java.time.Duration;
import java.util.logging.Logger;

// Models the four pipeline phases: OIDC auth, push, deploy, verify.
public class DeploymentPipeline {
    private static final Logger log = Logger.getLogger(DeploymentPipeline.class.getName());

    // OIDC: exchange a short-lived GitHub token for temporary AWS credentials.
    public String assumeRoleViaOidc(String repo, String branch, String roleArn) {
        if (!"main".equals(branch)) {
            throw new SecurityException("Trust policy: only main branch of " + repo + " may assume " + roleArn);
        }
        log.info(() -> "OIDC token for " + repo + "@" + branch + " exchanged via STS → temp creds (expire 15m)");
        return "temp-session-token"; // short-lived; never stored
    }

    // Push the image to ECR, tagged with the commit SHA for traceability.
    public String pushImage(String registry, String commitSha) {
        String image = registry + "/loan-service:" + commitSha;
        log.info(() -> "Pushed image " + image);
        return image;
    }

    // Deploy: point the Deployment at the new image and begin the rollout.
    public void deploy(Deployment d, String imageTag) {
        d.setTargetImageTag(imageTag);
        d.setStatus(RolloutStatus.IN_PROGRESS);
        log.info(() -> "helm upgrade --install → rolling out " + d.getName() + " to " + imageTag);
    }

    // Verify: block until pods are healthy. If unhealthy, FAIL and roll back.
    public boolean verifyRollout(Deployment d, int becameReady, Duration timeout) {
        d.setReadyReplicas(becameReady);
        boolean healthy = becameReady >= d.getDesiredReplicas();
        if (healthy) {
            d.setStatus(RolloutStatus.SUCCEEDED);
            d.promoteTargetToCurrent();
            log.info(() -> "Rollout SUCCEEDED: " + becameReady + "/" + d.getDesiredReplicas() + " ready");
            return true;
        }
        log.severe(() -> "Rollout FAILED: only " + becameReady + "/" + d.getDesiredReplicas()
                + " ready within " + timeout.toSeconds() + "s — rolling back");
        rollback(d);
        return false;
    }

    private void rollback(Deployment d) {
        d.setTargetImageTag(d.getCurrentImageTag());   // back to known-good
        d.setStatus(RolloutStatus.ROLLED_BACK);
        log.warning(() -> "helm rollback → " + d.getName() + " restored to " + d.getCurrentImageTag());
    }
}
