package com.bank.deploy;

import com.bank.deploy.model.Deployment;
import com.bank.deploy.pipeline.DeploymentPipeline;
import java.time.Duration;
import java.util.logging.*;

public class DeployDemoApplication {
    private static final Logger log = Logger.getLogger(DeployDemoApplication.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new DeployLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        DeploymentPipeline pipeline = new DeploymentPipeline();
        Deployment loan = new Deployment("loan-service", "v42", 3);

        // Phase 1: OIDC auth — no stored long-lived key.
        pipeline.assumeRoleViaOidc("bank/loan-service", "main",
                "arn:aws:iam::111122223333:role/gha-loan-service-deploy");

        // Phase 2: push image tagged with commit SHA.
        String image = pipeline.pushImage("111122223333.dkr.ecr.ap-south-1.amazonaws.com", "a1b2c3d");

        // Phase 3+4: healthy deploy — all 3 replicas become ready.
        pipeline.deploy(loan, image);
        pipeline.verifyRollout(loan, 3, Duration.ofSeconds(300));
        log.info(() -> "Live image now: " + loan.getCurrentImageTag() + " status=" + loan.getStatus());

        // Now simulate a BROKEN deploy: only 1 of 3 replicas become ready → rollback.
        String bad = pipeline.pushImage("111122223333.dkr.ecr.ap-south-1.amazonaws.com", "deadbee");
        pipeline.deploy(loan, bad);
        pipeline.verifyRollout(loan, 1, Duration.ofSeconds(300));
        log.info(() -> "After failed deploy, live image stays: " + loan.getCurrentImageTag()
                + " status=" + loan.getStatus());
    }
}

